// ─── File: DeepCloneDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.deepclone;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DeepCloneDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Holding reliance = new Holding("RELIANCE", 100, new BigDecimal("2450.50"));
        Holding tcs = new Holding("TCS", 50, new BigDecimal("3600.00"));
        Portfolio original = new Portfolio("Rajesh-PF", List.of(reliance, tcs));

        // TECHNIQUE 1: copy constructor (cascading deep copy).
        Portfolio copyCtor = new Portfolio(original);

        // TECHNIQUE 2: serialization round-trip.
        Portfolio copySerial = CloneUtil.deepCopyBySerialization(original);

        // TECHNIQUE 3: text/JSON-style round-trip.
        Portfolio copyText = CloneUtil.deepCopyByText(original);

        // Mutate the ORIGINAL after all clones were taken.
        original.getHoldings().get(0).setQuantity(999);
        original.getHoldings().get(0).setPrice(new BigDecimal("9999.99"));

        log.info(() -> "ORIGINAL first holding qty=" + original.getHoldings().get(0).getQuantity());
        log.info(() -> "copy(ctor)   first holding qty=" + copyCtor.getHoldings().get(0).getQuantity());
        log.info(() -> "copy(serial) first holding qty=" + copySerial.getHoldings().get(0).getQuantity());
        log.info(() -> "copy(text)   first holding qty=" + copyText.getHoldings().get(0).getQuantity());
    }
}

// ─── Would be in Holding.java (nested mutable object) ───
class Holding implements java.io.Serializable {
    private static final long serialVersionUID = 1L;
    private final String symbol;
    private int quantity;
    private BigDecimal price;
    Holding(String symbol, int quantity, BigDecimal price) {
        this.symbol = symbol; this.quantity = quantity; this.price = price;
    }
    // COPY CONSTRUCTOR for cascading deep copy.
    Holding(Holding other) { this(other.symbol, other.quantity, other.price); }
    String getSymbol() { return symbol; }
    int getQuantity() { return quantity; }
    void setQuantity(int q) { this.quantity = q; }
    BigDecimal getPrice() { return price; }
    void setPrice(BigDecimal p) { this.price = p; }
}

// ─── Would be in Portfolio.java (holds a list of Holding) ───
class Portfolio implements java.io.Serializable {
    private static final long serialVersionUID = 1L;
    private final String name;
    private final java.util.List<Holding> holdings;
    Portfolio(String name, java.util.List<Holding> holdings) {
        this.name = name; this.holdings = new java.util.ArrayList<>(holdings);
    }
    // COPY CONSTRUCTOR: deep-copies the list AND each Holding inside it.
    Portfolio(Portfolio other) {
        this.name = other.name;
        this.holdings = new java.util.ArrayList<>();
        for (Holding h : other.holdings) this.holdings.add(new Holding(h)); // cascade
    }
    String getName() { return name; }
    java.util.List<Holding> getHoldings() { return holdings; }
}

// ─── Would be in CloneUtil.java (serialization + text round-trip) ───
class CloneUtil {
    // Serialization round-trip: deep by construction, needs Serializable graph.
    @SuppressWarnings("unchecked")
    static <T extends java.io.Serializable> T deepCopyBySerialization(T obj) throws Exception {
        java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
        try (java.io.ObjectOutputStream out = new java.io.ObjectOutputStream(bytes)) {
            out.writeObject(obj);
        }
        try (java.io.ObjectInputStream in = new java.io.ObjectInputStream(
                new java.io.ByteArrayInputStream(bytes.toByteArray()))) {
            return (T) in.readObject();
        }
    }

    // Text/JSON-style round-trip: encode to a string then rebuild a NEW graph.
    // (A real system would use Jackson: mapper.readValue(mapper.writeValueAsString(obj), T.class).)
    static Portfolio deepCopyByText(Portfolio p) {
        StringBuilder sb = new StringBuilder(p.getName());
        for (Holding h : p.getHoldings()) {
            sb.append("|").append(h.getSymbol()).append(",")
              .append(h.getQuantity()).append(",").append(h.getPrice());
        }
        String[] parts = sb.toString().split("\\|");
        java.util.List<Holding> rebuilt = new java.util.ArrayList<>();
        for (int i = 1; i < parts.length; i++) {
            String[] f = parts[i].split(",");
            rebuilt.add(new Holding(f[0], Integer.parseInt(f[1]), new BigDecimal(f[2])));
        }
        return new Portfolio(parts[0], rebuilt);
    }
}
